/**
 * `github-repo` — ProjectResourceKind, spec §5.1 / §5.3.
 *
 * A single GitHub repository owned by a `github-org-admin`. The Access
 * bundle carries a **repo-scoped deploy token** (`GITHUB_TOKEN`) used
 * by CI / runners to clone, push tags, or interact with the repo's
 * Actions API.
 *
 * Rotation is `admin-mediated` (spec §0.1): the deploy token is
 * regenerated by the managing \`github-org-admin\` via the GitHub
 * Administration API, not by the user. The CRM "Rotate Access" flow
 * detects this and routes the request through the parent admin
 * Resource (Phase 6).
 *
 * No \`mcpFragment\` for this kind — a single repo is not a useful MCP
 * server. MCP tooling for GitHub is wired at the \`github-org\` or
 * \`github-org-admin\` level (org-wide context window).
 */

import type { ResourceKind } from '../../resource-kind.js';

interface GithubRepoMetadata {
  /** GitHub organization login owning the repo. */
  readonly org: string;
  /** Repository name (the part after `org/`). */
  readonly repo: string;
}

function isGithubRepoMetadata(value: unknown): value is GithubRepoMetadata {
  if (typeof value !== 'object' || value === null) return false;
  const v = value as { org?: unknown; repo?: unknown };
  return (
    typeof v.org === 'string' && v.org.length > 0 && typeof v.repo === 'string' && v.repo.length > 0
  );
}

const SETUP_DOCS = `## \`github-repo\` is admin-managed

You do **not** provision this Resource by pasting a token. A
\`github-repo\` is always created and rotated by its managing
\`github-org-admin\` Resource — see spec §0.1 (\`admin-mediated\`
rotation) and §5.3.

### How to add a github-repo to the CRM

1. Make sure your org already has a \`github-org-admin\` Resource
   registered. If not, follow the \`github-org-admin\` setup first.
2. Open the CRM "+ Add Resource" wizard, pick \`github-repo\`, and
   select the managing admin from the dropdown.
3. Choose **Create new** (the admin creates a fresh repo + deploy
   token on the GitHub API) or **Adopt existing** (the admin
   inventories an existing repo and issues a fresh deploy token for
   it).
4. The CRM seals the deploy token client-side and stores it under
   \`(resourceId, GITHUB_TOKEN)\` — cleartext never reaches the
   server (spec §4).

### What this token can do

The deploy token is repo-scoped and read-write on \`Contents\`,
\`Actions\`, \`Pull requests\` and \`Metadata\`. It is suitable for
CI, MCP per-repo tooling, and runner clone/push operations. It is
**not** an org-admin token — it cannot create new repos or modify
org settings.

### Rotation

Open the CRM resource page → "Rotate Access". The request is dispatched
to the managing \`github-org-admin\`, which calls the GitHub
Administration API to regenerate the deploy token. The new value is
sealed for the same recipient set and the old value becomes invalid
on GitHub's side within seconds.

### What if my managing admin is detached?

A \`github-repo\` with no live \`admin_resource_id\` link (spec §3.3)
cannot be rotated. The CRM surfaces a 409 with
\`rotationMethod=admin-mediated\` and a "Re-attach an admin" CTA.
Re-attach by editing the Resource and picking another live
\`github-org-admin\` from the same org.
`;

export const githubRepo: ResourceKind = {
  id: 'github-repo',
  provider: 'github',
  kindClass: 'project',
  displayName: 'GitHub repository',
  setupDocs: SETUP_DOCS,
  accessSchema: {
    GITHUB_TOKEN: {
      label: 'Repo-scoped deploy token',
      description:
        'Fine-grained PAT scoped to a single repo, issued and rotated by ' +
        'the managing `github-org-admin`. The CRM "+ Add Resource" wizard ' +
        'fills this for you — you do not paste it manually.',
      required: true,
      pattern: '^github_pat_[A-Za-z0-9_]{20,}$',
    },
  },
  metadataSchema: {
    description: 'GithubRepoMetadata: { org: string, repo: string }',
    fields: {
      org: { type: 'string', required: true },
      repo: { type: 'string', required: true },
    },
  },
  rotationMethod: 'admin-mediated',
  healthTestCmd(metadata, _access): string {
    if (!isGithubRepoMetadata(metadata)) {
      throw new Error('github-repo: invalid metadata, expected { org, repo }');
    }
    return (
      `curl -fsS -H "Authorization: Bearer $GITHUB_TOKEN" ` +
      `"https://api.github.com/repos/${metadata.org}/${metadata.repo}" | jq -e .full_name >/dev/null`
    );
  },
  // No mcpFragment: a single repo is not a useful MCP context root.
  // GitHub MCP exposure happens via the org-level kinds.
  egressHosts(_metadata): readonly string[] {
    return ['api.github.com', 'github.com'];
  },
};
